import{_ as o,a0 as n,w as r,s as d,ao as p,I as a,x as t,a1 as l,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"从实际代码开始编写好的示例 | LCTT x X-CMD","titleTemplate":false,"description":"从实际代码开始编写好的示例 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"从实际代码开始编写好的示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"从实际代码开始编写好的示例 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210708 Write good examples by starting with real code","title":"从实际代码开始编写好的示例","tag":"202107","desc":""},"relativePath":"202107/20210708 Write good examples by starting with real code.md","filePath":"[post].md"}'),u={name:"202107/20210708 Write good examples by starting with real code.md"};function m(b,e,h,g,k,f){const s=n("Link");return r(),d("div",null,[e[18]||(e[18]=p(`<h1 id="从实际代码开始编写好的示例" tabindex="-1">从实际代码开始编写好的示例 <a class="header-anchor" href="#从实际代码开始编写好的示例" aria-label="Permalink to “从实际代码开始编写好的示例”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202107/18/231616z1hhcerhrk3wzwkr.jpg" alt=""></p><p>当编写程序时，我花费了大量时间在编写好的示例上。我从未见过有人写过关于如何写出好的示例，所以我就写了一下如何写出一份好的示例。</p><p>基础思路就是从你写的真实代码开始，然后删除不相关的细节，使其成为一个独立的例子，而不是无中生有地想出一些例子。</p><p>我将会谈论两种示例：基于真实案例的示例和奇怪的示例</p><h3 id="好的示例是真实的" tabindex="-1">好的示例是真实的 <a class="header-anchor" href="#好的示例是真实的" aria-label="Permalink to “好的示例是真实的”">​</a></h3><p>为了说明为什么好的案例应该是真实的，我们就先讨论一个不真实的案例。假设我们在试图解释 Python 的 lambda 函数（这只是我想到的第一个概念）。你可以举一个例子，使用 <code>map</code> 和 lambda 来让一组数字变为原先的两倍。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>numbers = [1, 2, 3, 4]</span></span>
<span class="line"><span>squares = map(lambda x: x * x, numbers)</span></span></code></pre></div><p>我觉得这个示例不是真实的，有如下两方面的原因：</p><ul><li>将一组数字作平方运算不是在真实的程序中完成的事，除非是欧拉项目或某种东西（更多的可能是针对列表的操作）</li><li><code>map</code> 在 Python 中并不常用，即便是做这个我也更愿意写 <code>[x*x for x in numbers]</code></li></ul><p>一个更加真实的 Python lambdas 的示例是使用 <code>sort</code> 函数，就像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>children = [{&quot;name&quot;: &quot;ashwin&quot;, &quot;age&quot;: 12}, {&quot;name&quot;: &quot;radhika&quot;, &quot;age&quot;: 3}]</span></span>
<span class="line"><span>sorted_children = sorted(children, key=lambda x: x[&#39;age&#39;])</span></span></code></pre></div><p>但是这个示例是被精心设计的（为什么我们需要对这些孩子按照年龄进行排序呢？）。所以我们如何来做一个真实的示例呢？</p><h3 id="如何让你的示例真实起来-看你所写实际代码" tabindex="-1">如何让你的示例真实起来：看你所写实际代码 <a class="header-anchor" href="#如何让你的示例真实起来-看你所写实际代码" aria-label="Permalink to “如何让你的示例真实起来：看你所写实际代码”">​</a></h3><p>我认为最简单的来生成一个例子的方法就是，不是凭空出现一个例子（就像我用那个<code>儿童</code>的例子），而只是从真正的代码开始！</p><p>举一个例子吧，如果我要用 <code>sort.+key</code> 来编写一串 Python 代码，我会发现很多我按某个标准对列表进行排序的真实例子，例如：</p><ul><li><code>tasks.sort(key=lambda task: task[&#39;completed_time&#39;])</code></li><li><code>emails = reversed(sorted(emails, key=lambda x:x[&#39;receivedAt&#39;]))</code></li><li><code>sorted_keysizes = sorted(scores.keys(), key=scores.get)</code></li><li><code>shows = sorted(dates[date], key=lambda x: x[&#39;time&#39;][&#39;performanceTime&#39;])</code></li></ul><p>在这里很容易看到一个规律——这些基本是按时间排序的！因此，你可以明白如何将按时间排序的某些对象（电子邮件、事件等）的简单实例轻松地放在一起。</p><h3 id="现实的例子有助于-布道-你试图解释的概念" tabindex="-1">现实的例子有助于“布道”你试图解释的概念 <a class="header-anchor" href="#现实的例子有助于-布道-你试图解释的概念" aria-label="Permalink to “现实的例子有助于“布道”你试图解释的概念”">​</a></h3><p>当我试图去解释一个想法（就好比 Python Lambdas）的时候，我通常也会试图说服读者，说这是值得学习的想法。Python lambdas 是如此的有用！当我去试图说服某个人 lambdas 是很好用的时候，让他想象一下 lambdas 如何帮助他们完成一项他们将要去做的任务或是以及一项他们以前做过的任务，对说服他会很有帮助。</p><h3 id="从真实代码中提炼出示例可能需要很长时间" tabindex="-1">从真实代码中提炼出示例可能需要很长时间 <a class="header-anchor" href="#从真实代码中提炼出示例可能需要很长时间" aria-label="Permalink to “从真实代码中提炼出示例可能需要很长时间”">​</a></h3><p>我给出如何使用 <code>lambda</code> 和 <code>sort</code> 函数的解释例子是十分简单的，它并不需要花费我很长时间来想出来，但是将真实的代码提炼出为一个独立的示例则是会需要花费很长的时间！</p><p>举个例子，我想在这篇文章中融入一些奇怪的 CSS 行为的例子来说明创造一个奇怪的案例是十分有趣的。我花费了两个小时来解决我这周遇到的一个实际的问题，确保我理解 CSS 的实际情况，并将其变成一个小示例。</p>`,23)),a("p",null,[e[1]||(e[1]=t("最后，它“仅仅”用了 ",-1)),l(s,{href:"https://codepen.io/wizardzines/pen/0eda7725a46c919dcfdd3fa80aff3d41"},{default:i(()=>[...e[0]||(e[0]=[t("五行 HTML 和一点点的 CSS",-1)])]),_:1}),e[2]||(e[2]=t(" 来说明了这个问题，看起来并不想是我花费了好多小时写出来的。但是最初它却是几百行的 JS/CSS/JavaScript，它需要花费很长时间来将所有的代码化为核心的很少的代码。",-1))]),e[19]||(e[19]=a("p",null,"但我认为花点时间把示例讲得非常简单明了是值得的——如果有成百上千的人在读你的示例，你就节省了他们这么多时间！",-1)),e[20]||(e[20]=a("h3",{id:"就这么多了",tabindex:"-1"},[t("就这么多了！ "),a("a",{class:"header-anchor",href:"#就这么多了","aria-label":"Permalink to “就这么多了！”"},"​")],-1)),e[21]||(e[21]=a("p",null,"我觉得还有更多关于示例可以去讲的——几种不同类型的有用示例，例如：",-1)),e[22]||(e[22]=a("ul",null,[a("li",null,"可以更多的改变人的思维而不是直接提供使用的惊喜读者的示例代码"),a("li",null,"易于复制粘贴以用作初始化的示例")],-1)),e[23]||(e[23]=a("p",null,"也许有一天我还会再写一些呢？ 😃",-1)),e[24]||(e[24]=a("hr",null,null,-1)),a("p",null,[e[4]||(e[4]=t("via: ",-1)),l(s,{href:"https://jvns.ca/blog/2021/07/08/writing-great-examples/"},{default:i(()=>[...e[3]||(e[3]=[t("https://jvns.ca/blog/2021/07/08/writing-great-examples/",-1)])]),_:1})]),a("p",null,[e[9]||(e[9]=t("作者：",-1)),l(s,{href:"https://jvns.ca/"},{default:i(()=>[...e[5]||(e[5]=[t("Julia Evans",-1)])]),_:1}),e[10]||(e[10]=t(" 选题：",-1)),l(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[6]||(e[6]=[t("lujun9972",-1)])]),_:1}),e[11]||(e[11]=t(" 译者：",-1)),l(s,{href:"https://github.com/zepoch"},{default:i(()=>[...e[7]||(e[7]=[t("zepoch",-1)])]),_:1}),e[12]||(e[12]=t(" 校对：",-1)),l(s,{href:"https://github.com/turbokernel"},{default:i(()=>[...e[8]||(e[8]=[t("turbokernel",-1)])]),_:1})]),a("p",null,[e[15]||(e[15]=t("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原创编译，",-1)),l(s,{href:"https://linux.cn/"},{default:i(()=>[...e[14]||(e[14]=[t("Linux中国",-1)])]),_:1}),e[17]||(e[17]=t(" 荣誉推出",-1))])])}const C=o(u,[["render",m]]);export{y as __pageData,C as default};
